// 使用 .first() 避免 n8n 的 Paired Item 配對錯誤
const webhookItem = $('LINE Webhook').first();
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';

const isAddMode = text.includes('|加人') ? '|加人' : '';

const items = $input.all();
const groups = {};
const categoryOrder = {};

items.forEach(item => {
  const row = item.json;
  const category = row['服務分類'] || row['服務項目'] || '其他';
  const serviceName = String(row['服務項目'] || '');
  const duration = row['時長 (分鐘)'] || row['時長(分鐘)'] || '';
  const priceRaw = String(row['價格'] || '');
  const orderRaw = row['排序'];

  if (!serviceName) return;

  // 解析數字價格供排序使用
  const numericPrice = parseInt(priceRaw.replace(/[^\d]/g, ''), 10) || 0;

  // 1. 記錄分類排序權重
  const categorySortNum = (orderRaw !== undefined && orderRaw !== '' && !isNaN(orderRaw)) ? Number(orderRaw) : 999;
  if (categoryOrder[category] === undefined || categorySortNum < categoryOrder[category]) {
    categoryOrder[category] = categorySortNum;
  }

  // 2. 解析第一行與第二行內容
  const lines = serviceName.split('\n').map(s => s.trim()).filter(Boolean);
  const isMultiLine = lines.length > 1;
  const isPerCount = priceRaw.includes('/次');

  let line1 = lines[0] || '';
  let line2 = '';

  if (isMultiLine) {
    // 若原本就是 2 行（如套餐），直接拆成第一行與第二行
    line2 = lines[1] || '';
  } else if (!isPerCount) {
    // 若只有 1 行且非按次項目，第二行自動補上 (XX分鐘)
    line2 = `(${duration}分鐘)`;
  }

  const buttonLabel = priceRaw.startsWith('$') ? `預約 ${priceRaw}` : `預約 $${priceRaw}`;
  const cleanServiceName = serviceName.replace(/\n/g, ' ');

  if (!groups[category]) groups[category] = [];
  groups[category].push({
    line1: line1,
    line2: line2,
    duration: duration,
    numericPrice: numericPrice,
    buttonLabel: buttonLabel,
    actionText: `預約項目:${cleanServiceName}|${duration}${isAddMode}`
  });
});

// 大泡泡依據「排序」欄位進行排序（數字越小越靠左）
const sortedCategories = Object.keys(groups).sort((a, b) => categoryOrder[a] - categoryOrder[b]);

const bubbles = sortedCategories.map(category => {
  // 每個泡泡內的項目依據「價格」由便宜排到貴
  groups[category].sort((a, b) => a.numericPrice - b.numericPrice);

  const serviceBlocks = [];

  groups[category].forEach((svc, index) => {
    // 項目間分隔線
    if (index > 0) {
      serviceBlocks.push({
        "type": "separator",
        "margin": "sm"
      });
    }

    // 強制構造兩個獨立的 Text 區塊，保證元素行高與間距 100% 相同
    const textContents = [
      {
        "type": "text",
        "text": svc.line1,
        "size": "sm",
        "color": "#333333",
        "weight": "bold",
        "align": "center",
        "wrap": true
      }
    ];

    if (svc.line2) {
      textContents.push({
        "type": "text",
        "text": svc.line2,
        "size": "sm",
        "color": svc.line2.startsWith('(') ? "#666666" : "#333333", // 分鐘數用淺灰，套餐第二行用深黑
        "weight": "bold",
        "align": "center",
        "wrap": true
      });
    }

    // 組合整體區塊與按鈕
    serviceBlocks.push({
      "type": "box",
      "layout": "vertical",
      "margin": "sm",
      "spacing": "xs",
      "contents": [
        ...textContents,
        {
          "type": "button",
          "style": "secondary",
          "height": "sm",
          "margin": "xs",
          "action": {
            "type": "message",
            "label": svc.buttonLabel,
            "text": svc.actionText
          }
        }
      ]
    });
  });

  return {
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": category,
          "weight": "bold",
          "size": "md",
          "color": "#FFFFFF",
          "align": "center"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": serviceBlocks
    }
  };
});

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇您要預約的服務項目",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

// 使用 .first() 避免 n8n 配對錯誤
const webhookItem = $('LINE Webhook').first();
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';

const isAddMode = text.includes('|加人') ? '|加人' : '';
const parts = text.replace('預約項目:', '').replace('|加人', '').split('|');
const serviceName = parts[0];
const duration = parts[1] || '60';

const now = new Date();
const currentDay = now.getDate(); // 今天幾號

let totalDays = 0;

// 判斷邏輯：
if (currentDay >= 25) {
  // 25 號到月底：從今天起算固定 28 天 (4個泡泡)
  totalDays = 28;
} else {
  // 1 號到 25 號：從今天一直顯示到本月底
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const lastDayOfMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  totalDays = lastDayOfMonth - currentDay + 1;
}

// 計算需要幾週（每 7 天為一個 bubble，最多 4 個）
const totalWeeks = Math.ceil(totalDays / 7);
const oneDayTime = 24 * 60 * 60 * 1000;

const getTaiwanDate = (offsetDays = 0) => {
  const d = new Date(now.getTime() + (offsetDays * oneDayTime));
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Taipei',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return formatter.format(d);
};

const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
const bubbles = [];

for (let week = 0; week < totalWeeks; week++) {
  const dateBoxes = [];

  for (let i = 0; i < 7; i++) {
    const dayIndex = week * 7 + i;
    if (dayIndex >= totalDays) break;

    const dateStr = getTaiwanDate(dayIndex);
    const targetDate = new Date(now.getTime() + (dayIndex * oneDayTime));

    const dayOfWeek = targetDate.getDay(); 
    const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);

    const monthDay = `${targetDate.getMonth() + 1}/${targetDate.getDate()}`;
    const weekStr = `(週${weekdays[dayOfWeek]})`;
    const textColor = isWeekend ? '#FF4b4b' : '#333333';

    dateBoxes.push({
      "type": "box",
      "layout": "horizontal",
      "backgroundColor": "#f0f0f0",
      "cornerRadius": "sm",
      "paddingAll": "sm",
      "margin": "xs",
      "action": {
        "type": "message",
        "label": `${monthDay} ${weekStr}`,
        "text": `預約日期:${dateStr}|${serviceName}|${duration}${isAddMode}`
      },
      "contents": [
        {
          "type": "text",
          "text": `${monthDay} ${weekStr}`,
          "size": "md",
          "align": "center",
          "color": textColor,
          "weight": isWeekend ? "bold" : "regular"
        }
      ]
    });
  }

  const startDateStr = getTaiwanDate(week * 7);
  const actualEndIndex = Math.min((week * 7 + 6), totalDays - 1);
  const endDateStr = getTaiwanDate(actualEndIndex);

  const subTitle = `(${startDateStr.slice(5).replace('-', '-')} ~ ${endDateStr.slice(5).replace('-', '-')})`;
  const mainTitle = week === 0 ? '本週可預約日期' : `第 ${week + 1} 週`;

  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": mainTitle,
          "weight": "bold",
          "size": "sm",
          "color": "#FFFFFF",
          "align": "center"
        },
        {
          "type": "text",
          "text": subTitle,
          "size": "xs",
          "color": "#FFFFFFCC",
          "align": "center",
          "margin": "xs"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": dateBoxes
    }
  });
}

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇預約日期",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const text = $('LINE Webhook').item.json.body.events[0].message.text;
const isAddMode = text.includes('|加人') ? '|加人' : '';

const cleanText = text.replace('預約日期:', '').replace('|加人', '');
const parts = cleanText.split('|');
const dateStr = parts[0];
const serviceName = parts[1];
const duration = parts[2];

// 【關鍵修改】強制取得台灣時間 (UTC+8) 的當前日期與時間
const now = new Date();
// 將當前時間加上 8 小時的毫秒數來校正時區誤差
const twNow = new Date(now.getTime() + (8 * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));

const todayStr = `${twNow.getUTCFullYear()}-${String(twNow.getUTCMonth() + 1).padStart(2, '0')}-${String(twNow.getUTCDate()).padStart(2, '0')}`;
const currentHour = twNow.getUTCHours();
const currentMinute = twNow.getUTCMinutes();

// 建立完整原始時段清單
const rawTimes = [];
for (let hour = 11; hour <= 23; hour++) {
  rawTimes.push(`${String(hour).padStart(2, '0')}:00`);
  rawTimes.push(`${String(hour).padStart(2, '0')}:30`);
}
rawTimes.push('00:00');
rawTimes.push('00:30');
rawTimes.push('01:00');

// 過濾時間邏輯：如果是今天，過濾掉已經過去的時間
const times = rawTimes.filter(t => {
  if (dateStr !== todayStr) return true; // 如果不是今天，全部保留

  const [tHour, tMinute] = t.split(':').map(Number);

  // 處理跨日清晨時段
  if (tHour >= 0 && tHour <= 3) {
    return false; 
  }

  // 比較小時與分鐘 (使用台灣時間校正後的數值)
  if (tHour > currentHour) return true;
  if (tHour === currentHour && tMinute > currentMinute) return true;

  return false; 
});

// 如果今天所有時段都已經過期，回傳提示訊息
if (times.length === 0) {
  return {
    json: {
      replyToken: $('LINE Webhook').item.json.body.events[0].replyToken,
      messages: [
        {
          type: "text",
          text: `⚠️ 今日（${dateStr}）可預約的時間已經全部截止囉，請選擇其他日期進行預約！`
        }
      ]
    }
  };
}

const chunkSize = Math.ceil(times.length / 4);
const bubbles = [];

for (let week = 0; week < 4; week++) {
  const chunkTimes = times.slice(week * chunkSize, (week + 1) * chunkSize);
  if (chunkTimes.length === 0) continue;

  const timeBoxes = [];
  chunkTimes.forEach(t => {
    const isNextDay = t === '00:00' || t === '00:30' || t === '01:00';
    const labelDisplay = isNextDay ? `⏰ ${t} (次日)` : `⏰ ${t}`;

    timeBoxes.push({
      "type": "box",
      "layout": "horizontal",
      "backgroundColor": "#f0f0f0",
      "cornerRadius": "sm",
      "paddingAll": "sm",
      "margin": "xs",
      "action": {
        "type": "message",
        "label": `${t}${isNextDay ? ' (次日)' : ''}`,
        "text": `預約時間:${dateStr}|${t}|${serviceName}|${duration}${isAddMode}`
      },
      "contents": [
        {
          "type": "text",
          "text": labelDisplay,
          "size": "md",
          "align": "center",
          "color": isNextDay ? "#d9534f" : "#333333",
          "weight": "bold"
        }
      ]
    });
  });

  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": `選擇預約時間 (${week + 1}/4)`,
          "weight": "bold",
          "size": "sm",
          "color": "#FFFFFF",
          "align": "center"
        },
        {
          "type": "text",
          "text": `📅 ${dateStr}`,
          "size": "xs",
          "color": "#FFFFFFCC",
          "align": "center",
          "margin": "xs"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": timeBoxes
    }
  });
}

return {
  json: {
    "replyToken": $('LINE Webhook').item.json.body.events[0].replyToken,
    "messages": [
      {
        "type": "flex",
        altText: "請選擇預約時間",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const webhookItem = $('LINE Webhook').first();
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';

const isAddMode = text.includes('|加人') ? '|加人' : '';

let cleanText = text.replace('預約時間:', '').replace('預約師傅:', '').replace('|加人', '');
const parts = cleanText.split('|');

const dateStr = parts[0] ? parts[0].trim() : '';
const timeStr = parts[1] ? parts[1].trim() : ''; 
const serviceName = parts[2] || '按摩';
const duration = parseInt(parts[3] || '60', 10);

let scheduleRows = [];
let existingAppointments = [];

try {
  scheduleRows = $('讀取班表 Staff_Schedule').all().map(i => i.json);
} catch (e) {
  scheduleRows = [];
}

try {
  existingAppointments = $('讀取預約 Bookings').all().map(i => i.json);
} catch (e) {
  existingAppointments = [];
}

let availableStaff = [];

if (scheduleRows.length > 0) {
  const targetRow = scheduleRows.find(row => {
    const rowDate = String(row['日期'] || '').trim().substring(0, 10);
    return rowDate === dateStr;
  });

  if (targetRow) {
    const parseTimeToMinutes = (tStr) => {
      if (!tStr) return 0;
      const cleanT = String(tStr).replace(' (次日)', '').trim();
      const [h, m] = cleanT.split(':').map(Number);
      let totalM = (h || 0) * 60 + (m || 0);
      if (String(tStr).includes('次日') || (h || 0) < 6) {
        totalM += 24 * 60; 
      }
      return totalM;
    };

    const targetStartM = parseTimeToMinutes(timeStr);
    const targetEndM = targetStartM + duration;

    for (const [colName, workTime] of Object.entries(targetRow)) {
      if (colName === '日期' || colName === 'row_number') continue;
      if (!workTime || String(workTime).trim() === '') continue;

      const workStr = String(workTime).trim();
      if (workStr.includes('-')) {
        const [startPart, endPart] = workStr.split('-').map(s => s.trim());

        const parseWorkTime = (p) => {
          if (p.includes(':')) {
            const [h, m] = p.split(':').map(Number);
            return h * 60 + (m || 0);
          } else {
            const h = Math.floor(parseInt(p, 10) / 100);
            const m = parseInt(p, 10) % 100;
            return h * 60 + m;
          }
        };

        const workStartM = parseWorkTime(startPart);
        let workEndM = parseWorkTime(endPart);
        if (workEndM <= workStartM) workEndM += 24 * 60;

        if (targetStartM >= workStartM && targetEndM <= workEndM) {
          const colStr = String(colName).trim();
          let staffNum = '';
          let staffDisplayName = '';
          let emoji = '👨‍⚕️';

          if (colStr.includes('男')) {
            staffNum = colStr.replace('男', '').replace('號', '').trim();
            staffDisplayName = `${staffNum}號師傅`;
            emoji = '👨‍⚕️';
          } else if (colStr.includes('女')) {
            staffNum = colStr.replace('女', '').replace('號', '').trim();
            staffDisplayName = `${staffNum}號師傅`;
            emoji = '👩‍⚕️';
          } else {
            staffNum = colStr.replace('號', '').trim();
            staffDisplayName = `${staffNum}號師傅`;
          }

          let isConflict = false;
          existingAppointments.forEach(appt => {
            const apptDate = String(appt['預約日期'] || '').trim().substring(0, 10);
            const apptStaff = String(appt['指定師傅'] || appt['師傅姓名'] || '').trim();
            const apptStatus = String(appt['Status'] || appt['狀態'] || '').trim();

            if (apptDate === dateStr && apptStaff.includes(staffNum) && apptStatus !== '已取消') {
              const apptStartStr = String(appt['開始時間'] || '').trim();
              const apptEndStr = String(appt['結束時間'] || '').trim();

              if (apptStartStr && apptEndStr) {
                const apptStartM = parseTimeToMinutes(apptStartStr);
                const apptEndM = parseTimeToMinutes(apptEndStr);

                if (Math.max(targetStartM, apptStartM) < Math.min(targetEndM, apptEndM)) {
                  isConflict = true;
                }
              }
            }
          });

          if (!isConflict) {
            availableStaff.push({
              name: staffDisplayName,
              emoji: emoji,
              rawNum: parseInt(staffNum, 10) || 0
            });
          }
        }
      }
    }
  }
}

availableStaff.sort((a, b) => a.rawNum - b.rawNum);

// 關鍵修改點：當可用師傅 > 1 人時才提供「不指定」選項，若只有 1 人則直列該位師傅
const staffList = availableStaff.length > 1 
  ? ['不指定', ...availableStaff.map(s => s.name)] 
  : availableStaff.map(s => s.name);

const chunkSize = 5;
const bubbles = [];

const emojiMap = {};
availableStaff.forEach(s => {
  emojiMap[s.name] = s.emoji;
});

for (let i = 0; i < staffList.length; i += chunkSize) {
  const chunkStaff = staffList.slice(i, i + chunkSize);
  const staffBoxes = [];

  chunkStaff.forEach(s => {
    const isUnspecified = (s === '不指定');
    const emoji = isUnspecified ? '⭐' : (emojiMap[s] || '👨‍⚕️');

    staffBoxes.push({
      "type": "box",
      "layout": "horizontal",
      "backgroundColor": "#f0f0f0",
      "cornerRadius": "sm",
      "paddingAll": "sm",
      "margin": "xs",
      "action": {
        "type": "message",
        "label": s,
        "text": `預約師傅:${dateStr}|${timeStr}|${serviceName}|${duration}|${s}${isAddMode}`
      },
      "contents": [
        {
          "type": "text",
          "text": `${emoji} ${s}`,
          "size": "md",
          "align": "center",
          "color": "#333333",
          "weight": "bold"
        }
      ]
    });
  });

  const pageIndex = Math.floor(i / chunkSize) + 1;
  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": `選擇指定師傅 (${pageIndex})`,
          "weight": "bold",
          "size": "sm",
          "color": "#FFFFFF",
          "align": "center"
        },
        {
          "type": "text",
          "text": `⏰ ${dateStr} ${timeStr}`,
          "size": "xs",
          "color": "#FFFFFFCC",
          "align": "center",
          "margin": "xs"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": staffBoxes
    }
  });
}

if (availableStaff.length === 0) {
  return {
    json: {
      replyToken: replyToken,
      messages: [
        {
          "type": "flex",
          "altText": "預約時段已滿",
          "contents": {
            "type": "bubble",
            "body": {
              "type": "box",
              "layout": "vertical",
              "contents": [
                {
                  "type": "text",
                  "text": "真抱歉！",
                  "weight": "bold",
                  "size": "lg",
                  "color": "#FF4B4B"
                },
                {
                  "type": "text",
                  "text": `${dateStr} ${timeStr} 這個時段所有師傅均已被預約或休息，請重新選擇其他時間或日期。`,
                  "wrap": true,
                  "size": "md",
                  "margin": "md"
                }
              ]
            }
          }
        }
      ]
    }
  };
}

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇指定師傅",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const items = $input.all().map(i => i.json);
const webhookEvent = $('LINE Webhook').item.json.body.events[0];
const replyToken = webhookEvent.replyToken;
const userId = webhookEvent.source.userId;

console.log("=== 重複預約檢查開始 ===");

const now = new Date();
const getTaiwanDate = (offsetDays = 0) => {
  const d = new Date(now.getTime() + (offsetDays * 24 * 60 * 60 * 1000));
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Taipei',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
  return formatter.format(d);
};

const todayStr = getTaiwanDate(0);          // 今天 (2026-08-05)
const limitDateStr = getTaiwanDate(7);      // 7天內

