      }
    ]
  }
};

// 使用 .first() 安全取得 LINE Webhook 資訊，避免 Paired Item 配對錯誤
const webhookItem = $('LINE Webhook').first();
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';

// 組合全部取消成功的通知訊息
const messageText = `🗑️ 已為您成功取消所有預約！\n\n` +
  `您的所有預約行程已全數清空。\n` +
  `如有需要，歡迎隨時再次預約，期待您的光臨！`;

return {
