  replyToken = webhookData?.body?.events?.[0]?.replyToken || "";
} catch (e) {
  replyToken = "";
}

// 2. 取得員工資訊
let rawCode = "";
try {
  rawCode = $('比對USERID').first()?.json?.['編號'] || "";
} catch (e) {
  rawCode = "";
}

const numMatch = rawCode.match(/\d+/);
const staffNum = numMatch ? numMatch[0] : '';
const targetStaffName = `${staffNum}號師傅`;

// 3. 設定 7 天日期過濾區間 (從今日起算 7 天)
const today = new Date();
today.setHours(0, 0, 0, 0);

const next7Days = new Date(today);
next7Days.setDate(today.getDate() + 7);

// 4. 取得預約並過濾 (指定師傅 + 未來 7 天內)
const allBookings = $input.all();
const matchedBookings = allBookings
  .map(item => item.json)
  .filter(b => {
    const isStaff = (b['指定師傅'] === targetStaffName || b['指定師傅'] === rawCode);
    if (!isStaff || !b['預約日期']) return false;

    const bookingDate = new Date(b['預約日期']);
    bookingDate.setHours(0, 0, 0, 0);

    return bookingDate >= today && bookingDate < next7Days;
  })
  .sort((a, b) => new Date(`${a['預約日期']} ${a['開始時間']}`) - new Date(`${b['預約日期']} ${b['開始時間']}`));

// 5. 製作 Flex Message 泡泡 Body 內容
const contents = [];

if (matchedBookings.length === 0) {
  contents.push({
    type: "box",
    layout: "vertical",
    margin: "md",
