    let durationText = "";
    if (b['開始時間'] && b['結束時間']) {
      const [startH, startM] = b['開始時間'].split(':').map(Number);
      const [endH, endM] = b['結束時間'].split(':').map(Number);
      const durationMinutes = (endH * 60 + endM) - (startH * 60 + startM);
      if (durationMinutes > 0) {
        durationText = ` (${durationMinutes}分鐘)`;
      }
    }

    contents.push({
      type: "box",
      layout: "vertical",
      margin: index === 0 ? "none" : "md",
      spacing: "xs",
      contents: [
        // 第一行：日期
        {
          type: "box",
          layout: "baseline",
          contents: [
            {
              type: "text",
              text: `📅 ${b['預約日期']}`,
              weight: "bold",
              size: "md",
              color: "#1DB446"
            }
          ]
        },
        // 第二行：時間 + 分鐘數
        {
          type: "box",
          layout: "baseline",
          margin: "xs",
          contents: [
            {
              type: "text",
              text: `⏰ ${b['開始時間']} ~ ${b['結束時間']}${durationText}`,
              size: "md",
              color: "#333333",
              weight: "bold"
            }
          ]
        },
        // 第三行：服務項目
        {
          type: "box",
          layout: "baseline",
          margin: "xs",
          contents: [
            {
              type: "text",
              text: `💆 ${b['服務項目'] || '未指定'}`,
              size: "md",
              color: "#555555",
              weight: "bold"
            }
          ]
        },
        // 第四行：客戶姓名
        {
          type: "box",
          layout: "baseline",
          margin: "xs",
          contents: [
            {
              type: "text",
              text: `👤 ${displayName}`,
              size: "md",
              color: "#555555",
              weight: "bold"
            }
          ]
        }
      ]
    });

    if (index < matchedBookings.length - 1) {
      contents.push({
        type: "separator",
        margin: "md"
      });
    }
  });
}

// 6. 輸出標準 Flex Bubble 結構 (兩行式 Header，解決標題過長被截斷問題)
const flexMessage = {
  type: "flex",
  altText: `${targetStaffName} 近7日客戶預約表`,
  contents: {
    type: "bubble",
    size: "kilo",
    header: {
      type: "box",
      layout: "vertical",
      backgroundColor: "#0F2537",
      contents: [
        {
          type: "text",
          text: `📋 ${targetStaffName}`,
          weight: "bold",
          size: "md",
          color: "#FFFFFF"
        },
        {
          type: "text",
          text: "近 7 日客戶預約表",
          weight: "bold",
          size: "md",
          color: "#FFFFFF",
          margin: "xs"
        }
      ]
    },
    body: {
      type: "box",
      layout: "vertical",
      contents: contents
    }
  }
};

return [{
  json: {
    replyToken: replyToken,
    messages: [flexMessage]
  }
}];

