parameters.jsCode:
const matchedKey = $json.output.matched_key;
const rows = $('取得選單資料').all();

const row = rows.find(r => r.json['Trigger_Key (觸發關鍵字)'] === matchedKey);

if (!row) {
  return [{ json: { fallback: true } }];
}

let flexContents;
try {
  flexContents = JSON.parse(row.json['JSON_Content (JSON 內容)']);
} catch (e) {
  throw new Error('B欄JSON解析失敗：' + e.message);
}

return [{
  json: {
    replyToken: $('LINE Webhook').item.json.body.events[0].replyToken,
    messages: [
      {
        type: 'flex',
        altText: matchedKey,
        contents: flexContents
      }
    ]
  }
}];

// 取得 AI 輸出的原始文字
let rawOutput = $input.first().json.output || '';

// 尋找 JSON 的開頭 { 與結尾 }
let firstBrace = rawOutput.indexOf('{');
let lastBrace = rawOutput.lastIndexOf('}');

let isFlex = false;
let flexContent = null;

if (firstBrace !== -1 && lastBrace > firstBrace) {
  let jsonString = rawOutput.substring(firstBrace, lastBrace + 1);
  try {
    flexContent = JSON.parse(jsonString);
    isFlex = true;
  } catch (e) {
    isFlex = false;
  }
}

if (isFlex) {
  // 處理 contents：若原本是 carousel 或已是單一物件則保持原樣，若為單一項目的陣列則解開
  let targetContents = flexContent.contents || flexContent;
  if (Array.isArray(targetContents) && flexContent.type !== 'carousel') {
    targetContents = targetContents[0];
  }

  return [{
    json: {
      replyToken: $('LINE Webhook').item.json.body.events[0].replyToken,
      messages: [{
        type: "flex",
        altText: "增資資訊選單",
        contents: targetContents
      }]
    }
  }];
} else {
  return [{
    json: {
      replyToken: $('LINE Webhook').item.json.body.events[0].replyToken,
      messages: [{
        type: "text",
        text: rawOutput
      }]
    }
  }];
}

